void get_font_assembly_line(Tsys *sys, FONT_SETTINGS *dst) {
    if (!sys || !dst) return;
    dst->radius = 3.96429f;
    dst->small_radius_mul = 1.03571f;
    dst->medium_radius_mul = 2.255f;
    sys->memset(dst->width_mul, 0, sizeof(dst->width_mul));
    dst->width_mul[0] = 1.0f;
    dst->width_mul[1] = 0.471429f;
    dst->width_mul[2] = 0.842857f;
    dst->width_mul[3] = 1.65714f;
    dst->width_mul[4] = 0.7f;
    sys->memset(dst->width_flags, 0, sizeof(dst->width_flags));
    sys->memset(dst->move_desc_x, 0, sizeof(dst->move_desc_x));
    dst->move_desc_x[4] = 0.505494f;
    dst->move_desc_x[5] = 0.503297f;
    sys->memset(dst->move_desc_y, 0, sizeof(dst->move_desc_y));
    dst->move_desc_y[1] = 4.25847f;
    dst->move_desc_y[2] = 1.95122f;
    dst->move_desc_y[3] = 3.89224f;
    dst->move_desc_y[4] = 4.25266f;
    dst->move_desc_y[6] = 3.00623f;
    sys->memset(dst->move_grid_x, 0, sizeof(dst->move_grid_x));
    sys->memset(dst->move_grid_y, 0, sizeof(dst->move_grid_y));
    dst->half_width_settings_range_start = 0.607143f;
    dst->half_width_settings_range_end = 1.89286f;
    dst->descend = 1.0f;
    dst->optical_size = 0.0f;
    dst->glyph_count = FONT_ASSEMBLY_LINE_GLYPH_COUNT;
    dst->glyph_grid_size[0] = 14;
    dst->glyph_grid_size[1] = 22;
    dst->glyph_box_hsize[0] = 6.0f;
    dst->glyph_box_hsize[1] = 10.0f;
    dst->glyph_box_center[0] = 7.0f;
    dst->glyph_box_center[1] = 11.0f;
    dst->glyph_box_default_hw = 2.0f;
    dst->glyph_segment_data = (GlyphSegment *)sys->malloc((size_t)FONT_ASSEMBLY_LINE_SEG_COUNT * sizeof(GlyphSegment));
    dst->glyphs = (GLYPH_DATA *)sys->malloc((size_t)FONT_ASSEMBLY_LINE_GLYPH_COUNT * sizeof(GLYPH_DATA));
    if (!dst->glyphs || !dst->glyph_segment_data) return;
    for (int i = 0; i < FONT_ASSEMBLY_LINE_GLYPH_COUNT; i++) {
        GLYPH_DATA *gd = &dst->glyphs[i];
        int start = font_assembly_line_info[i].start;
        int count = font_assembly_line_info[i].count;
        gd->count = count;
        gd->segs = &dst->glyph_segment_data[start];
        for (int j = 0; j < count; j++) {
            unsigned int w0 = font_assembly_line_data[(start + j) * 2];
            unsigned int w1 = font_assembly_line_data[(start + j) * 2 + 1];
            gd->segs[j].type = GLYPH_UNPACK_MOVE(w0) ? SEG_LINE_MOVE : SEG_LINE_TO;
            gd->segs[j].x = (float)GLYPH_UNPACK_X4(w0) / 4.0f;
            gd->segs[j].y = (float)GLYPH_UNPACK_Y4(w0) / 4.0f;
            gd->segs[j].flags = (int)w1;
        }
    }
}

